const TITLE_CHARS:usize=80;
struct CheckResult{command:String,status:String}
fn fixture_strings(value:&Value)->Result<Vec<&str>,Box<dyn std::error::Error>>{if value.is_null(){return Ok(vec![])}value.as_array().ok_or("list required")?.iter().map(|v|v.as_str().ok_or_else(||"text required".into())).collect()}
